#pragma once

static const char SENSOR_PAGE[] =
"<!doctype html><html><head><meta name=viewport content='width=device-width,initial-scale=1'><title>Rover IMU</title><style>"
"*{box-sizing:border-box;letter-spacing:0}body{margin:0;background:#171b1d;color:#edf2f4;font-family:Arial,sans-serif}header{background:#111b25;border-bottom:3px solid #d39a00;padding:11px 12px}header div,main{max-width:900px;margin:auto}h1{font-size:20px;margin:0 0 5px}nav a{color:white;margin-right:14px;font-size:13px}.link{font-size:13px;color:#ff8d86}.up{color:#70dfa4}main{padding:12px}.panel{border:1px solid #3c4549;border-radius:8px;padding:12px;margin-bottom:12px;background:#1c2123}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.metric{border-left:4px solid #22b999;background:#132327;padding:10px;min-width:0}.metric small{display:block;color:#aab7bc}.metric strong{font-size:19px;overflow-wrap:anywhere}.views{display:grid;grid-template-columns:1fr 1fr;gap:12px}.instrument{display:grid;place-items:center;min-width:0}.instrument h2{font-size:15px;margin:0 0 7px}.horizon,.compass{width:min(75vw,300px);aspect-ratio:1;border:2px solid #657176;border-radius:50%;background:#132027}.compass{position:relative}.needle{position:absolute;left:calc(50% - 3px);top:12%;width:6px;height:42%;background:#e03027;transform-origin:50% 90%;border-radius:3px}.center{position:absolute;left:calc(50% - 6px);top:calc(50% - 6px);width:12px;height:12px;border-radius:50%;background:white}.actions{display:grid;grid-template-columns:1fr 1fr;gap:9px}button,input{font-size:15px}button{min-height:48px;border:1px solid #657176;border-radius:6px;background:#273035;color:white;font-weight:700}.primary{background:#1469a7;border-color:#1469a7}.danger{background:#b5261d;border-color:#b5261d}.warn{background:#d89a00;color:#121719;border-color:#d89a00}.slider{width:100%;height:42px;accent-color:#d89a00}.progress{height:10px;background:#0e1416;border-radius:5px;overflow:hidden;margin-top:8px}.progress i{display:block;height:100%;width:0;background:#22b999}.status{font:13px monospace;white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.5}.note{font-size:12px;color:#b2bdc1;line-height:1.5}.offsets{font-size:13px;color:#d4dde0}@media(max-width:650px){.views,.actions{grid-template-columns:1fr}.grid{grid-template-columns:1fr 1fr}}@media(max-width:390px){.grid{grid-template-columns:1fr}}"
"</style></head><body><header><div><h1>BNO080 Rover Orientation</h1><div id=link class=link>Connecting...</div><nav><a href='/'>Motors</a><a href='/mobile'>Drive</a><a href='/steppers'>Steppers</a><a href='/battery'>Battery</a></nav></div></header><main>"
"<section class=panel><div class=grid><div class=metric><small>Robot heading</small><strong id=heading>--</strong></div><div class=metric><small>Roll</small><strong id=roll>--</strong></div><div class=metric><small>Pitch</small><strong id=pitch>--</strong></div><div class=metric><small>Gyro X / Y / Z</small><strong id=gyro>--</strong></div><div class=metric><small>Mag accuracy</small><strong id=accuracy>--</strong></div><div class=metric><small>Telemetry age</small><strong id=age>--</strong></div></div></section>"
"<section class='panel views'><div class=instrument><h2>Artificial horizon</h2><canvas id=horizon class=horizon width=300 height=300></canvas></div><div class=instrument><h2>Corrected heading</h2><div class=compass><div id=needle class=needle></div><div class=center></div></div></section>"
"<section class=panel><h2>Mounting calibration</h2><div class=actions><button class=primary onclick=level()>Calibrate level</button><button class=warn onclick=forwardCal()>Calibrate forward heading</button></div><label class=note>Forward-test throttle: <output id=throttleOut>100%</output><input id=throttle class=slider type=range min=20 max=100 value=100 oninput=\"document.getElementById('throttleOut').value=this.value+'%'\"></label><div class=actions><button class=danger onclick=post('/api/sensors/calibration/abort')>ABORT / STOP</button><button onclick=resetCal()>Reset mounting calibration</button></div><div class=progress><i id=progress></i></div><p id=calStatus class=status>Idle</p><p id=offsets class=offsets></p><p class=note>Level calibration requires about one second completely motionless. Forward calibration counts down for 3 seconds, ramps to the selected power over one second, and measures the first coherent acceleration interval. Clear a long path and be ready to stop the rover. This estimates the IMU mounting yaw; it does not replace BNO080 hard/soft-iron magnetometer calibration.</p></section>"
"<section class=panel><div id=vectors class=status>Waiting for vectors...</div><div id=diagnostic class=note></div><p><a href='/api/sensors/calibration/log' download>Download last forward-calibration black box CSV</a></p></section>"
"</main><script>const e=x=>document.getElementById(x),f=(x,n=1)=>Number(x).toFixed(n),v=(a,n=3)=>a?a.map(x=>(x>=0?'+':'')+Number(x).toFixed(n)).join('  '):'--';let last={};function horizon(roll,pitch){const c=e('horizon'),x=c.getContext('2d'),w=c.width,h=c.height;x.clearRect(0,0,w,h);x.save();x.beginPath();x.arc(w/2,h/2,w/2-3,0,Math.PI*2);x.clip();x.translate(w/2,h/2);x.rotate(-roll*Math.PI/180);let py=Math.max(-80,Math.min(80,pitch*3));x.fillStyle='#27658b';x.fillRect(-w,-h+py,w*2,h);x.fillStyle='#62513a';x.fillRect(-w,py,w*2,h);x.strokeStyle='white';x.lineWidth=3;x.beginPath();x.moveTo(-w,py);x.lineTo(w,py);x.stroke();for(let d=-30;d<=30;d+=10){if(!d)continue;let y=py-d*3;x.lineWidth=1;x.beginPath();x.moveTo(-35,y);x.lineTo(35,y);x.stroke()}x.restore();x.strokeStyle='#dfe8eb';x.lineWidth=3;x.beginPath();x.moveTo(95,150);x.lineTo(135,150);x.lineTo(150,163);x.lineTo(165,150);x.lineTo(205,150);x.stroke()}function render(s){last=s;e('link').textContent=s.connected?'BNO080 streaming | '+s.age_ms+' ms':s.phase+(s.error?' | '+s.error:'');e('link').className='link '+(s.connected?'up':'');e('heading').textContent=s.connected?f(s.corrected_heading_deg)+' deg':'--';e('roll').textContent=s.connected?f(s.corrected_roll_deg)+' deg':'--';e('pitch').textContent=s.connected?f(s.corrected_pitch_deg)+' deg':'--';e('gyro').textContent=s.connected?v(s.gyro_rad_s,2):'--';e('accuracy').textContent=s.magnetometer_accuracy+' / 3';e('age').textContent=s.age_ms>=0?s.age_ms+' ms':'--';e('needle').style.transform='rotate('+Number(s.corrected_heading_deg||0)+'deg)';horizon(Number(s.corrected_roll_deg||0),Number(s.corrected_pitch_deg||0));e('progress').style.width=s.calibration_progress+'%';e('calStatus').textContent=(s.calibration_active?'ACTIVE: ':'')+s.calibration_phase+(s.calibration_error?'\\n'+s.calibration_error:'');e('offsets').textContent='Level '+(s.level_calibrated?'saved':'not set')+' | roll '+f(s.level_roll_offset_deg)+' deg, pitch '+f(s.level_pitch_offset_deg)+' deg | Forward '+(s.heading_calibrated?'saved':'not set')+' | yaw '+f(s.heading_offset_deg)+' deg';e('vectors').textContent='Raw heading '+f(s.heading_deg)+' deg\\nquaternion i j k real  '+v(s.quaternion,5)+'\\nmagnetic uT            '+v(s.magnetic_uT,3)+'\\nacceleration m/s2      '+v(s.acceleration_m_s2,3)+'\\nlinear accel m/s2      '+v(s.linear_acceleration_m_s2,3);e('diagnostic').textContent='UART TX GPIO'+s.tx_gpio+' / RX GPIO'+s.rx_gpio+' @ '+s.baud+' | reports '+s.reports+' | '+s.phase}function load(){fetch('/api/sensors',{cache:'no-store'}).then(r=>r.json()).then(render).catch(x=>e('diagnostic').textContent='Request failed: '+x.message)}function post(url){fetch(url,{method:'POST',cache:'no-store'}).then(async r=>{if(!r.ok)throw Error(await r.text());return r.json()}).then(render).catch(x=>alert(x.message))}function level(){if(confirm('Keep the rover level and completely still. Start calibration?'))post('/api/sensors/calibration/level')}function forwardCal(){if(confirm('CLEAR A LONG PATH. The rover will count down, then drive forward for 3 seconds. Continue?'))post('/api/sensors/calibration/forward?throttle='+e('throttle').value)}function resetCal(){if(confirm('Delete saved level and heading offsets?'))post('/api/sensors/calibration/reset')}setInterval(load,250);load()</script></body></html>";
